p = Path('enrichment/v7/work/t1_s087_20261009/out/luna-max/c649.jsonl')
items = [json.loads(line) for line in p.read_text().splitlines()]
by_loc = {item['loc']: item for item in items}
original_rows = {item['loc']: list(item['rows']) for item in items}
